export const SERVICE_IDS = Object.keys(AIVEN_SERVICE_ICONS);

/** Recommended pixel sizes by context. */
export const ICON_SIZES = { tableRow: 28, card: 40, detailHeader: 48, marketing: 64 };

const norm = (s) => String(s).toLowerCase().replace(/[®™]/g, '').replace(/aiven for /g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

const LOOKUP = (() => {
  const map = new Map();
  for (const icon of Object.values(AIVEN_SERVICE_ICONS)) {
    map.set(norm(icon.id), icon);
    map.set(norm(icon.name), icon);
    for (const a of icon.aliases) map.set(norm(a), icon);
  }
  return map;
})();

/** Resolve a service name / alias to an icon record, or null if unsupported. */
export function getServiceIcon(query) {
  if (!query) return null;
  const k = norm(query);
  if (LOOKUP.has(k)) return LOOKUP.get(k);
  for (const [key, icon] of LOOKUP) {
    if (key.length > 3 && (k.includes(key) || key.includes(k))) return icon;
  }
  return null;
}

/** Raw inline SVG markup for a service, or null. */
export function getServiceIconSvg(query) {
  const icon = getServiceIcon(query);
  return icon ? icon.svg : null;
}

/** A ready-to-inject <span> wrapper at a given pixel size. */
export function serviceIconHtml(query, size = 40) {
  const icon = getServiceIcon(query);
  if (!icon) return '';
  return '<span role="img" aria-label="' + icon.name + '" style="display:inline-flex;width:' +
    size + 'px;height:' + size + 'px;flex:none">' + icon.svg + '</span>';
}
